#!/usr/bin/env gjs -m
/**
 * Resource Pulse - Hardware Tracker Accuracy & Dynamic Benchmark Harness
 * 
 * Tests the metric samplers (lib/cpu.js, lib/memory.js, lib/disk.js)
 * against synthetic ground-truth workloads generated by tests/workload_generator.py.
 */

import Gio from 'gi://Gio';
import GLib from 'gi://GLib';
import { CpuSampler } from '../lib/cpu.js';
import { MemorySampler } from '../lib/memory.js';
import { DiskSampler } from '../lib/disk.js';

// ANSI colors
const BOLD = '\x1b[1m';
const GREEN = '\x1b[32m';
const RED = '\x1b[31m';
const YELLOW = '\x1b[33m';
const CYAN = '\x1b[36m';
const RESET = '\x1b[0m';
const DIM = '\x1b[2m';

function sleep(ms) {
    return new Promise(resolve => GLib.timeout_add(GLib.PRIORITY_DEFAULT, ms, () => {
        resolve();
        return GLib.SOURCE_REMOVE;
    }));
}

// Independent ground truth for CPU tests: the CPU time the worker processes
// themselves consumed, from /proc/<pid>/stat (utime + stime, in clock ticks).
const CLK_TCK = 100;
function readText(path) {
    try {
        const [, bytes] = GLib.file_get_contents(path);
        return new TextDecoder().decode(bytes);
    } catch (e) {
        return null; // process exited: a normal event
    }
}
function descendantPids(pid) {
    const out = [];
    const stack = [pid];
    while (stack.length) {
        const p = stack.pop();
        const tasks = Gio.File.new_for_path(`/proc/${p}/task`);
        let children = '';
        try {
            const en = tasks.enumerate_children('standard::name', Gio.FileQueryInfoFlags.NONE, null);
            let info;
            while ((info = en.next_file(null)))
                children += ` ${readText(`/proc/${p}/task/${info.get_name()}/children`) || ''}`;
            en.close(null);
        } catch (e) {}
        for (const c of children.trim().split(/\s+/).filter(Boolean).map(Number)) {
            out.push(c);
            stack.push(c);
        }
    }
    return out;
}
function processTicks(pids) {
    let total = 0;
    for (const pid of pids) {
        const stat = readText(`/proc/${pid}/stat`);
        if (!stat) continue;
        const f = stat.slice(stat.lastIndexOf(')') + 2).split(' ');
        total += Number(f[11]) + Number(f[12]);
    }
    return total;
}

function printHeader(title) {
    print(`\n${BOLD}${CYAN}=== ${title} ===${RESET}`);
}

function printResultRow(metric, target, measured, unit, errorPct, status, extra = '') {
    const statusStr = status ? `${GREEN}${BOLD}✓ PASS${RESET}` : `${RED}${BOLD}✗ FAIL${RESET}`;
    const errStr = errorPct !== null ? `${errorPct.toFixed(1)}%` : 'N/A';
    print(`  ${metric.padEnd(20)} | Target: ${target.padEnd(10)} | Measured: ${measured.padEnd(10)} ${unit.padEnd(5)} | Dev: ${errStr.padEnd(7)} | ${statusStr} ${extra ? `(${extra})` : ''}`);
}

export class BenchmarkSuite {
    constructor() {
        this._cpu = new CpuSampler();
        this._mem = new MemorySampler();
        this._dsk = new DiskSampler();
        this._results = [];
        // Next to this file, wherever the command is run from.
        const [here] = GLib.filename_from_uri(import.meta.url);
        this._scriptPath = GLib.build_filenamev([GLib.path_get_dirname(here), 'workload_generator.py']);
    }

    async init() {
        // Prime samplers (baseline ticks)
        await this._cpu.sample(true);
        await this._mem.sample();
        await this._dsk.sample(true);
        await sleep(1000);
        await this._cpu.sample(true);
        await this._mem.sample();
        await this._dsk.sample(true);
    }

    _spawnWorker(args) {
        const fullArgs = ['python3', this._scriptPath, ...args];
        const proc = Gio.Subprocess.new(
            fullArgs,
            Gio.SubprocessFlags.STDOUT_PIPE | Gio.SubprocessFlags.STDERR_MERGE
        );
        return proc;
    }

    /**
     * Wait until the worker has written its ready file. A worker that is not
     * running would otherwise surface as a misleading accuracy FAIL.
     */
    async _waitReady(proc, readyFile, timeoutMs = 5000) {
        try {
            for (let waited = 0; waited < timeoutMs; waited += 100) {
                if (GLib.file_test(readyFile, GLib.FileTest.EXISTS)) return;
                if (proc.get_if_exited()) break;
                await sleep(100);
            }
            let output = '';
            if (proc.get_if_exited()) {
                const bytes = proc.get_stdout_pipe().read_bytes(65536, null);
                output = new TextDecoder().decode(bytes.toArray()).trim();
            }
            throw new Error(`workload worker did not start (${this._scriptPath})${output ? `:\n${output}` : ''}`);
        } finally {
            try { GLib.unlink(readyFile); } catch (e) {}
        }
    }

    _readyFile() {
        return GLib.build_filenamev([GLib.get_tmp_dir(), `rp_bench_ready_${GLib.get_monotonic_time()}.tmp`]);
    }

    async _stopWorker(proc) {
        if (proc.get_if_exited()) return;
        try {
            proc.send_signal(15); // SIGTERM allows Python cleanup() handler to terminate workers
        } catch (e) {}
        await sleep(300);
        try {
            proc.force_exit();
        } catch (e) {}
        await sleep(800); // Allow OS and drives to settle
    }

    // --------------------------------------------------------------------------
    // 1. Static CPU Accuracy Test
    // --------------------------------------------------------------------------
    async testCpu(targetCores = 2, duration = 6.5) {
        printHeader(`Static CPU Benchmark (${targetCores} cores saturated @ 100%)`);

        // Measure baseline
        const bSample1 = await this._cpu.sample(true);
        await sleep(1000);
        const bSample2 = await this._cpu.sample(true);
        await sleep(1000);
        const bSample3 = await this._cpu.sample(true);
        const baseCpu = (bSample1.total + bSample2.total + bSample3.total) / 3;
        const totalThreads = bSample2.threadsCount || bSample2.cores.length || 12;
        const expectedDelta = (targetCores / totalThreads) * 100;
        const expectedTotal = Math.min(100, baseCpu + expectedDelta);

        print(`  Baseline CPU: ${baseCpu.toFixed(1)}% across ${totalThreads} logical threads`);
        print(`  Spawning ${targetCores} worker process(es)... Expected total: ~${expectedTotal.toFixed(1)}%`);

        const readyFile = this._readyFile();
        const proc = this._spawnWorker([
            '--cpu-cores', targetCores.toString(),
            '--duration', duration.toString(),
            '--ready-file', readyFile
        ]);

        let measured, workerShare, background, avgTopCoreLoad;
        try {
            await this._waitReady(proc, readyFile);
            await sleep(1200); // Settling time

            // One 3 s window measured two ways: the sampler's system total,
            // and the workers' own CPU time (ground truth). Background load
            // on a desktop moves by several points between any baseline and
            // the window, which swamps a 1-core signal on many-thread
            // machines, so the sampler is judged against the workers
            // measured over the same window instead of against a baseline.
            const pids = descendantPids(proc.get_identifier());
            await this._cpu.sample(true);
            const t0 = GLib.get_monotonic_time();
            const ticks0 = processTicks(pids);
            await sleep(3000);
            const s1 = await this._cpu.sample(true);
            const ticks1 = processTicks(pids);
            const dt = (GLib.get_monotonic_time() - t0) / 1e6;

            measured = s1.total;
            workerShare = ((ticks1 - ticks0) / CLK_TCK / dt) / totalThreads * 100;
            background = measured - workerShare;
            const sortedCores = [...s1.cores].sort((x, y) => y - x);
            const topCores = sortedCores.slice(0, targetCores);
            avgTopCoreLoad = topCores.reduce((x, y) => x + y, 0) / topCores.length;
        } finally {
            await this._stopWorker(proc);
        }

        // 1. The load really ran (workers got >= 80% of their cores).
        // 2. The sampler did not under-report: system total >= the workers'
        //    own share (1.5 points allowed for tick rounding).
        // 3. It did not over-report: what is left for everything else is
        //    within 10 points of the idle baseline.
        const loadRan = workerShare >= expectedDelta * 0.8;
        const notUnder = measured >= workerShare - 1.5;
        const notOver = background <= baseCpu + 10;
        const passed = loadRan && notUnder && notOver;
        // No single deviation figure: the three conditions above are the verdict.
        const errorPct = null;
        this._results.push({ name: `CPU (${targetCores} cores)`, passed });

        printResultRow(
            'CPU Total Load',
            `≥${workerShare.toFixed(1)}%`,
            `${measured.toFixed(1)}%`,
            '%',
            errorPct,
            passed,
            `workers ${workerShare.toFixed(1)}% of ${expectedDelta.toFixed(1)}% expected · others ${background.toFixed(1)}% (idle ${baseCpu.toFixed(1)}%) · top ${targetCores} core avg ${avgTopCoreLoad.toFixed(1)}%`
        );
        if (!loadRan) print(`  ${YELLOW}Workload did not get its cores; result says nothing about the sampler.${RESET}`);

        await sleep(1000); // Allow CPU to settle back
    }

    // --------------------------------------------------------------------------
    // 2. Static Memory Allocation Accuracy Test
    // --------------------------------------------------------------------------
    async testMemory(targetMb = 500, duration = 4.0) {
        printHeader(`Static Memory Benchmark (+${targetMb} MB RAM allocated & dirtied)`);

        const bMem = await this._mem.sample();
        const baseUsedMb = bMem.used / (1024 * 1024);
        print(`  Baseline Memory: ${baseUsedMb.toFixed(0)} MB used / ${(bMem.total / (1024 * 1024)).toFixed(0)} MB total`);

        const readyFile = this._readyFile();
        const proc = this._spawnWorker([
            '--mem-mb', targetMb.toString(),
            '--duration', duration.toString(),
            '--ready-file', readyFile
        ]);

        let measuredDeltaMb;
        try {
            await this._waitReady(proc, readyFile);
            await sleep(1000); // Settling time (allocation is finished in the worker)
            const lMem = await this._mem.sample();
            measuredDeltaMb = Math.max(0, lMem.used / (1024 * 1024) - baseUsedMb);
        } finally {
            await this._stopWorker(proc);
        }
        const errorPct = Math.abs(measuredDeltaMb - targetMb) / targetMb * 100;

        // Tolerance: +/- 15% (process overhead & background allocations)
        const passed = Math.abs(measuredDeltaMb - targetMb) <= (targetMb * 0.15);
        this._results.push({ name: `Memory (+${targetMb} MB)`, passed });

        printResultRow(
            'RAM Allocation',
            `+${targetMb} MB`,
            `+${measuredDeltaMb.toFixed(0)} MB`,
            'MB',
            errorPct,
            passed
        );

        await sleep(1000);
    }

    // --------------------------------------------------------------------------
    // 3. Static Disk Write Throughput Test
    // --------------------------------------------------------------------------
    async testDisk(targetMbS = 25, duration = 4.0) {
        printHeader(`Static Disk I/O Benchmark (Throttled write @ ${targetMbS} MB/s)`);

        await this._dsk.sample(true);
        await sleep(1000);
        const bDsk = await this._dsk.sample(true);
        const baseWriteRateMb = bDsk.writeRate / (1024 * 1024);
        print(`  Baseline Write: ${baseWriteRateMb.toFixed(1)} MB/s`);

        const readyFile = this._readyFile();
        const proc = this._spawnWorker([
            '--disk-mbs', targetMbS.toString(),
            '--duration', duration.toString(),
            '--ready-file', readyFile
        ]);

        let measuredRateMb, lDsk;
        try {
            await this._waitReady(proc, readyFile);
            await this._dsk.sample(true);
            await sleep(1500); // One window entirely under load
            lDsk = await this._dsk.sample(true);
            measuredRateMb = lDsk.writeRate / (1024 * 1024);
        } finally {
            await this._stopWorker(proc);
        }
        const errorPct = Math.abs(measuredRateMb - targetMbS) / targetMbS * 100;

        // Tolerance: +/- 25% (write cache / flush timing). Too fast fails too.
        const passed = Math.abs(measuredRateMb - targetMbS) <= (targetMbS * 0.25);
        this._results.push({ name: `Disk Write (${targetMbS} MB/s)`, passed });

        printResultRow(
            'Disk Write Rate',
            `${targetMbS} MB/s`,
            `${measuredRateMb.toFixed(1)} MB/s`,
            'MB/s',
            errorPct,
            passed,
            `Disk Percent: ${Math.round(lDsk.diskPercent)}%`
        );

        await sleep(1000);
    }

    // --------------------------------------------------------------------------
    // 4. Dynamic Time-Varying Step-Response Benchmark
    // --------------------------------------------------------------------------
    async testDynamic() {
        printHeader('Dynamic Step-Response Benchmark (Time-Varying Load)');
        print(`  ${DIM}Tracking real-time response latency and step transitions...${RESET}`);

        const proc = this._spawnWorker(['--dynamic']);
        const pipe = new Gio.DataInputStream({ base_stream: proc.get_stdout_pipe() });

        const phaseResults = [];
        let currentPhase = null;
        let phaseStartTime = 0;
        let detectedTime = 0;

        // Monitor phases asynchronously while sampling
        let running = true;
        let workerDied = false;
        // The sequence lasts ~14 s; never sample longer than this.
        const deadline = GLib.get_monotonic_time() + 60 * 1000000;
        const readLoop = async () => {
            while (running) {
                const [line] = await new Promise((resolve) => {
                    pipe.read_line_async(GLib.PRIORITY_DEFAULT, null, (stream, res) => {
                        try {
                            resolve(stream.read_line_finish_utf8(res));
                        } catch (e) {
                            resolve([null]);
                        }
                    });
                });
                if (line === null) {
                    // Worker exited (or never started) without [DYNAMIC_END]:
                    // stop sampling instead of looping forever.
                    running = false;
                    workerDied = true;
                    break;
                }
                const trimmed = line.trim();

                if (trimmed.startsWith('[PHASE_START]')) {
                    const matchName = trimmed.match(/name=(\w+)/);
                    const matchCpu = trimmed.match(/cpu_cores=(\d+)/);
                    const matchMem = trimmed.match(/mem_mb=(\d+)/);
                    const matchDisk = trimmed.match(/disk_mbs=(\d+)/);

                    currentPhase = {
                        name: matchName ? matchName[1] : 'UNKNOWN',
                        expectedCpuCores: matchCpu ? parseInt(matchCpu[1], 10) : 0,
                        expectedMemMb: matchMem ? parseInt(matchMem[1], 10) : 0,
                        expectedDiskMbs: matchDisk ? parseInt(matchDisk[1], 10) : 0,
                        samples: []
                    };
                    phaseStartTime = GLib.get_monotonic_time();
                    detectedTime = 0;
                } else if (trimmed.startsWith('[PHASE_END]')) {
                    if (currentPhase) {
                        phaseResults.push(currentPhase);
                        currentPhase = null;
                    }
                } else if (trimmed.startsWith('[DYNAMIC_END]')) {
                    running = false;
                    break;
                }
            }
        };

        let lastSampleTime = GLib.get_monotonic_time();
        const samplingLoop = async () => {
            while (running) {
                if (GLib.get_monotonic_time() > deadline) {
                    running = false;
                    workerDied = true;
                    break;
                }
                await sleep(800); // 800ms sampling tick for fast responsive tracking
                const now = GLib.get_monotonic_time();
                const c = await this._cpu.sample(true);
                const m = await this._mem.sample();
                const d = await this._dsk.sample(true);

                if (currentPhase) {
                    const timeElapsedMs = (now - phaseStartTime) / 1000;
                    const sampleData = {
                        timeOffsetMs: timeElapsedMs,
                        cpu: c.total,
                        cores: c.cores,
                        memUsedMb: m.used / (1024 * 1024),
                        writeMbS: d.writeRate / (1024 * 1024)
                    };
                    currentPhase.samples.push(sampleData);

                    const sortedCores = [...c.cores].sort((a, b) => b - a);
                    const top2Avg = (sortedCores[0] + (sortedCores[1] || 0)) / 2;

                    // Check detection latency for step changes
                    if (currentPhase.name === 'HIGH_LOAD' && detectedTime === 0) {
                        if (sampleData.writeMbS >= 10.0 || top2Avg >= 60.0) {
                            detectedTime = timeElapsedMs;
                            currentPhase.latencyMs = detectedTime;
                        }
                    } else if (currentPhase.name === 'STEP_DOWN' && detectedTime === 0) {
                        if (sampleData.writeMbS <= 18.0) {
                            detectedTime = timeElapsedMs;
                            currentPhase.latencyMs = detectedTime;
                        }
                    } else if (currentPhase.name === 'RECOVERY' && detectedTime === 0) {
                        if (sampleData.writeMbS <= 3.0) {
                            detectedTime = timeElapsedMs;
                            currentPhase.latencyMs = detectedTime;
                        }
                    }
                }
            }
        };

        try {
            await Promise.all([readLoop(), samplingLoop()]);
        } finally {
            await this._stopWorker(proc);
        }
        const expectedPhases = ['BASELINE', 'HIGH_LOAD', 'STEP_DOWN', 'RECOVERY'];
        if (workerDied || expectedPhases.some(n => !phaseResults.find(p => p.name === n))) {
            print(`  ${RED}${BOLD}Workload sequence did not complete${RESET} (${this._scriptPath}); phases seen: ${phaseResults.map(p => p.name).join(', ') || 'none'}`);
            this._results.push({ name: 'Dynamic Step-Response & Recovery', passed: false });
            return;
        }

        // Calibrate baseline from BASELINE phase samples
        let baseCpu = 0;
        let baseMemMb = 0;
        let baseDsk = 0;
        const baselinePhase = phaseResults.find(p => p.name === 'BASELINE');
        if (baselinePhase && baselinePhase.samples.length > 0) {
            const sumCpu = baselinePhase.samples.reduce((a, s) => a + s.cpu, 0);
            const sumMem = baselinePhase.samples.reduce((a, s) => a + s.memUsedMb, 0);
            const sumDsk = baselinePhase.samples.reduce((a, s) => a + s.writeMbS, 0);
            baseCpu = sumCpu / baselinePhase.samples.length;
            baseMemMb = sumMem / baselinePhase.samples.length;
            baseDsk = sumDsk / baselinePhase.samples.length;
        }

        print(`  Calibrated Baseline: CPU=${baseCpu.toFixed(1)}%, RAM=${baseMemMb.toFixed(0)} MB, Disk=${baseDsk.toFixed(1)} MB/s\n`);
        print(`  ${BOLD}Dynamic Transition Evaluation:${RESET}`);

        let allDynamicPassed = true;

        for (const pr of phaseResults) {
            if (pr.name === 'BASELINE') {
                print(`    Phase [${pr.name}]: Baseline verified.`);
            } else if (pr.name === 'HIGH_LOAD') {
                const lastSample = pr.samples[pr.samples.length - 1] || {};
                const deltaCpu = (lastSample.cpu || 0) - baseCpu;
                const deltaMem = (lastSample.memUsedMb || 0) - baseMemMb;
                const writeRate = lastSample.writeMbS || 0;
                const latencyStr = pr.latencyMs ? `${pr.latencyMs.toFixed(0)} ms` : '< 1000 ms';

                const sortedCores = [...(lastSample.cores || [])].sort((a, b) => b - a);
                const top2Avg = ((sortedCores[0] || 0) + (sortedCores[1] || 0)) / 2;

                const cpuOk = top2Avg >= 65.0; // 2 cores saturated
                const memOk = deltaMem >= 450; // at least 450 MB of 600 MB
                const diskOk = writeRate >= 16.0; // at least 16 MB/s of 25 MB/s
                const fastResponse = !pr.latencyMs || pr.latencyMs <= 2000;

                const pass = cpuOk && memOk && diskOk && fastResponse;
                if (!pass) allDynamicPassed = false;

                const status = pass ? `${GREEN}PASS${RESET}` : `${RED}FAIL${RESET}`;
                print(`    Phase [${pr.name}]: Top-2 Cores=${top2Avg.toFixed(1)}%, +${deltaMem.toFixed(0)} MB RAM, ${writeRate.toFixed(1)} MB/s Disk`);
                print(`      Response Latency: ${latencyStr} | Tracking Accuracy: ${status}`);
            } else if (pr.name === 'STEP_DOWN') {
                const lastSample = pr.samples[pr.samples.length - 1] || {};
                const deltaMem = (lastSample.memUsedMb || 0) - baseMemMb;
                const writeRate = lastSample.writeMbS || 0;

                const sortedCores = [...(lastSample.cores || [])].sort((a, b) => b - a);
                const topCore = sortedCores[0] || 0;
                const secondCore = sortedCores[1] || 0;

                // 1 core hot, 1 core dropped, RAM dropped to ~300 MB, Disk dropped to ~10 MB/s
                const cpuStepped = topCore >= 65.0 && secondCore <= 45.0;
                const memStepped = deltaMem <= 400 && deltaMem >= 150;
                const diskStepped = writeRate <= 18.0 && writeRate >= 5.0;

                const pass = cpuStepped && memStepped && diskStepped;
                if (!pass) allDynamicPassed = false;

                const status = pass ? `${GREEN}PASS${RESET}` : `${RED}FAIL${RESET}`;
                print(`    Phase [${pr.name}]: 1-Core Active (${topCore.toFixed(1)}%), +${deltaMem.toFixed(0)} MB RAM, ${writeRate.toFixed(1)} MB/s Disk`);
                print(`      Step-Down Tracking: ${status}`);
            } else if (pr.name === 'RECOVERY') {
                const lastSample = pr.samples[pr.samples.length - 1] || {};
                const deltaMem = Math.abs((lastSample.memUsedMb || 0) - baseMemMb);
                const writeRate = lastSample.writeMbS || 0;

                const sortedCores = [...(lastSample.cores || [])].sort((a, b) => b - a);
                const topCore = sortedCores[0] || 0;

                const pass = topCore <= 40.0 && deltaMem <= 120 && writeRate <= 5.0;
                if (!pass) allDynamicPassed = false;

                const status = pass ? `${GREEN}PASS${RESET}` : `${RED}FAIL${RESET}`;
                print(`    Phase [${pr.name}]: Settled back to Baseline (Top Core=${topCore.toFixed(1)}%, ΔRAM=${deltaMem.toFixed(0)} MB, Write=${writeRate.toFixed(1)} MB/s)`);
                print(`      Recovery Verification: ${status}`);
            }
        }

        this._results.push({ name: 'Dynamic Step-Response & Recovery', passed: allDynamicPassed });
    }

    printSummary() {
        printHeader('Benchmark Test Results Summary');
        let allPassed = true;
        for (const res of this._results) {
            const icon = res.passed ? `${GREEN}${BOLD}✓ PASS${RESET}` : `${RED}${BOLD}✗ FAIL${RESET}`;
            print(`  ${icon} - ${res.name}`);
            if (!res.passed) allPassed = false;
        }
        print('\n' + '='.repeat(60));
        if (allPassed) {
            print(`${GREEN}${BOLD}ALL BENCHMARKS PASSED!${RESET} Hardware metrics accurately track static and dynamic workloads.\n`);
        } else {
            print(`${RED}${BOLD}SOME BENCHMARKS FAILED.${RESET} Check detailed output above.\n`);
        }
        return allPassed;
    }
}

// ------------------------------------------------------------------------------
// Main Execution
// ------------------------------------------------------------------------------
const loop = GLib.MainLoop.new(null, false);

async function main() {
    const suite = new BenchmarkSuite();
    await suite.init();

    const mode = (ARGV[0] || 'all').toLowerCase();

    if (mode === 'cpu') {
        const cores = parseInt(ARGV[1] || '2', 10);
        await suite.testCpu(cores);
    } else if (mode === 'mem' || mode === 'memory') {
        const mb = parseInt(ARGV[1] || '500', 10);
        await suite.testMemory(mb);
    } else if (mode === 'disk') {
        const mbs = parseInt(ARGV[1] || '25', 10);
        await suite.testDisk(mbs);
    } else if (mode === 'dynamic') {
        await suite.testDynamic();
    } else if (mode === 'static') {
        await suite.testCpu(2);
        await suite.testMemory(500);
        await suite.testDisk(25);
    } else {
        // 'all' runs both static and dynamic suites
        await suite.testCpu(2);
        await suite.testMemory(500);
        await suite.testDisk(25);
        await suite.testDynamic();
    }

    const passed = suite.printSummary();
    if (!passed) {
        throw new Error('Benchmark suite encountered test failures.');
    }
}

main()
    .then(() => loop.quit())
    .catch((e) => {
        print(`\n${RED}${BOLD}[ERROR]${RESET} ${e.message}`);
        loop.quit();
        // Exit with non-zero status
        imports.system.exit(1);
    });

loop.run();
